<?php

declare(strict_types=1);

namespace Machma\Forms\Config;

/**
 * Read access to config/compiled.php (generated by bin/compile-config.php).
 *
 * @phpstan-type Site array{id:string, origins:list<string>, fromName:string, recipients:array<string,array{to:list<string>,cc:list<string>,bcc:list<string>}>, rateLimit:array{perIp:int,windowMinutes:int}, locales:list<string>, dryRun:bool, forms:array<string,array<string,mixed>>}
 */
final class Config
{
    /** @param array{generatedAt?:string, sites:array<string,array<string,mixed>>, users:array<string,array{role:string,sites:list<string>}>} $data */
    public function __construct(private readonly array $data)
    {
    }

    public static function load(string $file): self
    {
        if (!is_file($file)) {
            return new self(['sites' => [], 'users' => []]);
        }
        /** @var array $data */
        $data = require $file;
        return new self($data);
    }

    /** @return array<string, mixed>|null */
    public function site(string $id): ?array
    {
        return $this->data['sites'][$id] ?? null;
    }

    /** @return array<string, array<string, mixed>> */
    public function sites(): array
    {
        return $this->data['sites'];
    }

    /** @return array<string, mixed>|null */
    public function form(string $siteId, string $formId): ?array
    {
        return $this->data['sites'][$siteId]['forms'][$formId] ?? null;
    }

    /** @return array{role:string, sites:list<string>}|null */
    public function user(string $email): ?array
    {
        return $this->data['users'][strtolower($email)] ?? null;
    }

    /** @return array<string, array{role:string, sites:list<string>}> */
    public function users(): array
    {
        return $this->data['users'];
    }

    public function generatedAt(): ?string
    {
        return $this->data['generatedAt'] ?? null;
    }
}
